import React, { useState, useEffect } from 'react';
import { AlertCircle, CheckCircle, Clock, Server } from 'lucide-react';

function SystemStatus() {
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lastChecked, setLastChecked] = useState(null);

  const fetchStatus = async () => {
    try {
      const response = await fetch('/api/news/status');
      const data = await response.json();

      if (data.success) {
        setStatus(data.data);
        setLastChecked(new Date());
      }
    } catch (error) {
      console.error('获取状态失败:', error);
      setStatus({
        status: '错误',
        error: '无法连接到服务器',
        newsCount: 0,
        isUsingDemo: true
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 30000); // 每30秒检查一次
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="fixed bottom-4 right-4 bg-blue-500 text-white px-4 py-2 rounded-lg shadow-lg">
        <div className="flex items-center space-x-2">
          <Server className="w-4 h-4 animate-pulse" />
          <span>检查系统状态...</span>
        </div>
      </div>
    );
  }

  if (!status) return null;

  const isDemoMode = status.isUsingDemo || status.status === '演示模式';
  const statusColor = isDemoMode ? 'bg-yellow-500' : 'bg-green-500';
  const StatusIcon = isDemoMode ? AlertCircle : CheckCircle;

  return (
    <div className="fixed bottom-4 right-4 z-50">
      <div className={`${statusColor} text-white px-4 py-3 rounded-lg shadow-lg max-w-sm`}>
        <div className="flex items-start space-x-3">
          <StatusIcon className="w-5 h-5 mt-0.5 flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between">
              <h4 className="font-medium text-sm">
                {isDemoMode ? '演示模式' : '系统正常'}
              </h4>
              <div className="flex items-center text-xs opacity-75">
                <Clock className="w-3 h-3 mr-1" />
                {lastChecked ? lastChecked.toLocaleTimeString() : ''}
              </div>
            </div>

            {isDemoMode && (
              <div className="mt-1 text-xs opacity-90">
                <p>当前显示示例数据，真实RSS源连接中</p>
                <p className="mt-1">新闻数量: {status.newsCount} 条</p>
              </div>
            )}

            {!isDemoMode && (
              <div className="mt-1 text-xs opacity-90">
                <p>新闻数量: {status.newsCount} 条</p>
                {status.categories && status.categories.length > 0 && (
                  <p>分类: {status.categories.slice(0, 3).map(c => c.name).join(', ')}</p>
                )}
              </div>
            )}

            {status.status === '错误' && (
              <div className="mt-1 text-xs opacity-90">
                <p>{status.error}</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default SystemStatus;
